{
  "claims": [
    {
      "agent": "NOC",
      "type": "action",
      "verb": "rollback_change",
      "params": {"change_ticket": "CHG-1"},
      "inject_refs": ["S1-I1", "S1-I2"],
      "rationale": "CHG-1 lowered route-flood protection limit from 100 to 50 and removed inbound route filter; three minutes later core site A isolated. The ticket includes a rollback plan to restore previous snapshot.",
      "evidence": [
        {"chunk_id": "US-FCC-ATT-2024-REPORT#0001", "quote": "Once implemented, this configuration error caused the AT&T Mobility network to enter “protect mode” to prevent impact to other services, disconnecting all devices from the network, and prompting a loss of voice and 5G data service for all wireless users. It took close to two hours to roll back the network change."}
      ]
    },
    {
      "agent": "NOC",
      "type": "action",
      "verb": "alt_auth_route",
      "params": {"target_site": "core site B", "region": "R2"},
      "inject_refs": ["S1-I2"],
      "rationale": "Emergency-call routing for R2 shows no path after core site A isolation; core site B is healthy with spare capacity.",
      "evidence": [
        {"chunk_id": "UK-OFCOM-BT-999-2024#0001", "quote": "Being able to contact the emergency services can mean the difference between life and death, so in the event of any disruption to their networks, providers must be ready to respond quickly and effectively."}
      ]
    },
    {
      "agent": "NOC",
      "type": "obligation",
      "statement": "NOC must notify TDRA of the unplanned outage within 2 hours of discovering it.",
      "inject_refs": ["S1-I6", "S1-I7"],
      "rationale": "TDRA has received no notice from any operator as of T+35, and the duty officer is seeking the deadline; global precedent requires 2-hour notification to national regulators.",
      "evidence": [
        {"chunk_id": "CA-CRTC-2025-225#0023", "quote": "Major primary service outage: TSPs must notify the Commission, ISED, and FPT EMOs within two hours."}
      ],
      "deadline_hours": 2
    },
    {
      "agent": "NOC",
      "type": "obligation",
      "statement": "NOC must notify the 999 emergency call centre within 30 minutes of discovering the emergency-call outage.",
      "inject_refs": ["S1-I3"],
      "rationale": "999 centre saw call volume drop to near zero and social media reports of failed emergency calls, but no operator contacted the centre; global precedent requires PSAP notification within 30 minutes for 9-1-1-type outages.",
      "evidence": [
        {"chunk_id": "CA-CRTC-2025-225#0023", "quote": "Major 9-1-1 service outage: 9-1-1 network providers and originating network providers must notify (i) PSAPs within 30 minutes; and (ii) the Commission, ISED, and FPT EMOs within two hours."}
      ],
      "deadline_hours": 0.5
    },
    {
      "agent": "NOC",
      "type": "obligation",
      "statement": "NOC must ensure that emergency calls in R2 are carried to the relevant termination point; failure to do so is a fundamental breach.",
      "inject_refs": ["S1-I2"],
      "rationale": "Emergency-call routing for R2 shows no path, and emergency call access is a fundamental legal obligation.",
      "evidence": [
        {"chunk_id": "AU-ACMA-OPTUS-2026#0000", "quote": "Giving access to the emergency call service is not optional, it is a fundamental legal obligation and the most important public safety responsibility telecommunications providers have."}
      ],
      "deadline_hours": null
    },
    {
      "agent": "NOC",
      "type": "action",
      "verb": "preserve_logs",
      "params": {"scope": "core logs last 24 hours"},
      "inject_refs": ["S1-I4"],
      "rationale": "Vendor requests full core logs; NOC should preserve logs locally for incident investigation before any transfer is considered.",
      "evidence": [
        {"chunk_id": "ITU-T-Y3177#0027", "quote": "In the fault detection phase, the data collection functions receive and store operational data from the underlay network through reference point (4)-1."}
      ]
    },
    {
      "agent": "NOC",
      "type": "action",
      "verb": "enable_review_queue",
      "params": {"change_type": "AI/closed-loop network changes"},
      "inject_refs": ["S1-I1"],
      "rationale": "The change was auto-approved by the closed-loop optimiser with sandbox stage skipped; NOC must enable human review queue to prevent unsafe automated changes.",
      "evidence": [
        {"chunk_id": "ITU-T-Y3172#0037", "quote": "NOTE – The sandbox subsystem is not shown for simplicity in Figure I.1, but its functionality is applicable also to Figure I.1."},
        {"chunk_id": "ITU-T-Y3173#0025", "quote": "Automatic closed-loop under the operator provided intent or policy is introduced as the cornerstone of network automation."}
      ]
    },
    {
      "agent": "NOC",
      "type": "action",
      "verb": "disable_tool",
      "params": {"tool": "closed-loop network optimiser"},
      "inject_refs": ["S1-I1"],
      "rationale": "The closed-loop optimiser generated and auto-approved a change that caused core isolation; disabling the tool prevents further unsafe auto-changes until governance is in place.",
      "evidence": [
        {"chunk_id": "ITU-T-Y3173#0025", "quote": "Automatic closed-loop under the operator provided intent or policy is introduced as the cornerstone of network automation."}
      ]
    },
    {
      "agent": "NOC",
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No rule requires that AI/closed-loop network changes with impact on core routing and emergency services undergo sandbox testing and human review before auto-approval.",
      "inject_refs": ["S1-I1"],
      "rationale": "CHG-1 was raised by the closed-loop optimiser and auto-approved with the sandbox stage skipped; subsequent core isolation shows the absence of a mandatory gating rule.",
      "evidence": [
        {"chunk_id": "ITU-T-Y3172#0037", "quote": "NOTE – The sandbox subsystem is not shown for simplicity in Figure I.1, but its functionality is applicable also to Figure I.1."}
      ],
      "global_examples": [
        {"chunk_id": "US-FCC-ATT-2024-REPORT#0001", "quote": "Once implemented, this configuration error caused the AT&T Mobility network to enter “protect mode” to prevent impact to other services, disconnecting all devices from the network, and prompting a loss of voice and 5G data service for all wireless users."}
      ]
    },
    {
      "agent": "EMS",
      "type": "action",
      "verb": "activate_alt_channels",
      "params": {"region": "R2"},
      "inject_refs": ["S1-I3"],
      "rationale": "999 call volume dropped to near zero and social media reports calls failing, including to 999; EMS must activate alternative channels for emergency contact.",
      "evidence": [
        {"chunk_id": "AU-ACMA-TELSTRA-2024#0000", "quote": "Telstra has been open and apologetic about the outage, communicated effectively to the public and took a variety of immediate actions when problems were identified."}
      ]
    },
    {
      "agent": "EMS",
      "type": "action",
      "verb": "public_alert",
      "params": {"region": "R2"},
      "inject_refs": ["S1-I3"],
      "rationale": "Public reports show calls fail including 999; EMS should issue a public alert about alternative emergency contact methods.",
      "evidence": [
        {"chunk_id": "AU-ACMA-TELSTRA-2024#0000", "quote": "Telstra has been open and apologetic about the outage, communicated effectively to the public and took a variety of immediate actions when problems were identified."}
      ]
    },
    {
      "agent": "CSC",
      "type": "action",
      "verb": "issue_advisory",
      "params": {"target": "NOC", "subject": "halt unsanctioned bulk upload of subscriber-level data outside UAE"},
      "inject_refs": ["S1-I5"],
      "rationale": "National monitoring flagged a scheduled bulk upload of subscriber-level data outside UAE; CSC should issue advisory to stop and investigate before transfer.",
      "evidence": [
        {"chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000", "quote": "The regulator said OTPs should not be shared through weak modes of communication"}
      ]
    },
    {
      "agent": "CSC",
      "type": "action",
      "verb": "notify",
      "params": {"recipient": "DPA", "subject": "scheduled bulk upload of subscriber-level data outside UAE"},
      "inject_refs": ["S1-I5"],
      "rationale": "CSC should notify the data protection authority about the flagged transfer so DPA can assess.",
      "evidence": [
        {"chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000", "quote": "The regulator said OTPs should not be shared through weak modes of communication"}
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "assess_transfer",
      "params": {"transfer": "bulk upload of core logs with MSISDNs/IMSIs to offshore AI support region"},
      "inject_refs": ["S1-I4", "S1-I5"],
      "rationale": "The vendor request and scheduled bulk upload involve subscriber identifiers leaving UAE; DPA must assess the transfer's lawfulness and safeguards.",
      "evidence": [
        {"chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000", "quote": "The regulator said OTPs should not be shared through weak modes of communication"}
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "open_investigation",
      "params": {"subject": "potential unauthorised personal data export of subscriber MSISDNs/IMSIs"},
      "inject_refs": ["S1-I5"],
      "rationale": "Scheduled bulk upload of subscriber-level data outside UAE may constitute a personal data breach; DPA should investigate.",
      "evidence": [
        {"chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000", "quote": "The regulator said OTPs should not be shared through weak modes of communication"}
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "request_breach_report",
      "params": {"party": "OpCo", "subject": "scheduled bulk upload and vendor data request"},
      "inject_refs": ["S1-I4", "S1-I5"],
      "rationale": "DPA should require OpCo to report details of the data transfer, data categories, recipients, and legal basis.",
      "evidence": [
        {"chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000", "quote": "The regulator said OTPs should not be shared through weak modes of communication"}
      ]
    },
    {
      "agent": "DPA",
      "type": "insufficient_evidence",
      "statement": "No UAE-specific data export or international transfer rules are included in the knowledge excerpts, so the lawfulness of the offshore AI support region transfer cannot be determined.",
      "inject_refs": ["S1-I4", "S1-I5"],
      "evidence": [
        {"chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000", "quote": "The Central Bank of the UAE has not officially announced the cancellation of SMS or email OTPs."}
      ]
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "open_incident",
      "params": {"incident": "R2 outage affecting emergency calls"},
      "inject_refs": ["S1-I6"],
      "rationale": "TDRA has received no notice from any operator; REG should open an incident to investigate the outage and compliance with notification duties.",
      "evidence": [
        {"chunk_id": "UK-OFCOM-BT-999-2024#0000", "quote": "BT notified Ofcom of this issue, as required by law, and on 28 June 2023 Ofcom opened an investigation to establish whether the company had failed to comply with its legal duties to take appropriate and proportionate measures to prepare for potential disruption to its network."}
      ]
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "request_report",
      "params": {"party": "OpCo", "report_type": "initial and post-outage reports"},
      "inject_refs": ["S1-I6", "S1-I7"],
      "rationale": "REG should request detailed outage report from OpCo, including cause, impact, and restoration timeline.",
      "evidence": [
        {"chunk_id": "US-CFR-47-4-9#0004", "quote": "shall submit electronically a Notification to the Commission within 120 minutes of discovering such outage. Not later than 72 hours after discovering the outage, the provider(s) shall submit electronically an Initial Communications Outage Report to the Commission."}
      ]
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "public_statement",
      "params": {"topic": "R2 outage and AI involvement"},
      "inject_refs": ["S1-I6"],
      "rationale": "Journalist asks whether AI is running network unsupervised; REG should issue a public statement to address concerns while investigation is ongoing.",
      "evidence": [
        {"chunk_id": "AU-ACMA-TELSTRA-2024#0000", "quote": "Telstra has been open and apologetic about the outage, communicated effectively to the public and took a variety of immediate actions when problems were identified."}
      ]
    },
    {
      "agent": "REG",
      "type": "obligation",
      "statement": "REG must apply a 2-hour notification deadline for operators to report unplanned major outages, consistent with international precedent.",
      "inject_refs": ["S1-I7"],
      "rationale": "TDRA duty officer is asking for the deadline; REG must clarify and enforce the 2-hour rule.",
      "evidence": [
        {"chunk_id": "CA-CRTC-2025-225#0023", "quote": "Major primary service outage: TSPs must notify the Commission, ISED, and FPT EMOs within two hours."}
      ],
      "deadline_hours": 2
    },
    {
      "agent": "REG",
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "No UAE operator licence deadline for unplanned outage notification to TDRA is evidenced; the internal question at S1-I7 shows the deadline is unknown.",
      "inject_refs": ["S1-I7"],
      "rationale": "TDRA duty officer asks how many hours are required, indicating lack of a clear rule; international precedents set 120 minutes/2 hours.",
      "evidence": [
        {"chunk_id": "CA-CRTC-2025-225#0023", "quote": "Major primary service outage: TSPs must notify the Commission, ISED, and FPT EMOs within two hours."},
        {"chunk_id": "US-CFR-47-4-9#0004", "quote": "shall submit electronically a Notification to the Commission within 120 minutes of discovering such outage."}
      ],
      "global_examples": [
        {"chunk_id": "CA-CRTC-2025-225#0023", "quote": "Major primary service outage: TSPs must notify the Commission, ISED, and FPT EMOs within two hours."},
        {"chunk_id": "US-CFR-47-4-9#0004", "quote": "shall submit electronically a Notification to the Commission within 120 minutes of discovering such outage."}
      ]
    }
  ]
}
